import {BODIES} from './architecture.js';import {toWorld} from './pose.js';
export function faultMapSVG(s){let out='<svg xmlns="http://www.w3.org/2000/svg" viewBox="-8 -10 159 112" role="img" aria-label="故障停止の実配置と高さ・現在位置"><rect x="-8" y="-10" width="159" height="112" fill="#e3e8e0"/>';
 for(const b of BODIES){const p=s.positions[b.id];for(const[cx,cz]of b.cells){const points=[[cx*8,cz*8],[cx*8+8,cz*8],[cx*8+8,cz*8+8],[cx*8,cz*8+8]].map(([x,z])=>{const q=toWorld(p,{x,z});return q.x+','+q.z;}).join(' ');out+=`<polygon data-fault-body="${b.id}" points="${points}" fill="${b.color}" fill-opacity=".55" stroke="#546e62" stroke-width=".12"/>`;}out+=`<text x="${p.x+4}" y="${p.z+3}" text-anchor="middle" font-size=".9">${b.id}</text><text x="${p.x+4}" y="${p.z+5}" text-anchor="middle" font-size=".65">Y${p.y.toFixed(2)}</text>`;}
 const p=s.player;return out+`<circle data-fault-player="true" cx="${p.x}" cy="${p.z}" r=".5" fill="#d35332"/><text x="0" y="-4" font-size="1.2">故障 A→B ${s.fault.time.toFixed(1)}秒 / 実位置の高さ別投影</text><text x="0" y="96" font-size="1">現在 X${p.x.toFixed(2)} Y${p.y.toFixed(2)} Z${p.z.toFixed(2)} / ${s.fault.motion.control==='walk'?'歩行・重力':'開発上下移動'}</text></svg>`;}
